      const offset = params.has("offset") ? params.get("offset").split(",") : [];
      const x = s11ParseInt(offset[0]), y = s11ParseInt(offset[1]), zoom = s11ParseInt(offset[2]);
      const dest = zoom === null ? [page - 1, { name: "FitBH" }, y] : [page - 1, { name: "XYZ" }, x, y, zoom];
