  const aspect = Math.atan2(from.height, from.width);
  if (angle > -aspect && angle <= aspect) return "right";
  if (angle > aspect && angle <= Math.PI - aspect) return "bottom";
  if (angle > Math.PI - aspect || angle <= -(Math.PI - aspect)) return "left";
  return "top";
