/** The regex that detects a #tag trigger at the end of the text before the cursor. */
const s21TagTriggerRe = /(^|\s)#[^\u2000-\u206F\u2E00-\u2E7F'!"#$%&()*+,.:;<=>?@^`{|}~\[\]\\\s]*$/g;

// =====================================================================================================================
// Plain function replacements (manifest "entries"); they reach app internals through the lazy env binding.
// =====================================================================================================================

/** Tag suggestions scored against the metadata cache; `withHash` keeps the leading '#' on the returned tags. */
function s21TagSuggestions(cache, query, withHash) {
  if (withHash === undefined) withHash = false;
  query = query.toLowerCase();
  let tags = Object.keys(cache.getTags());
  if (!withHash) tags = tags.map((tag) => tag.slice(1));
  const results = [];
  const prepared = prepareQuery(query);
  tags.sort(s04StringCompare);
  for (const tag of tags) {
    if (query === "" || (query === "#" && withHash)) {
      results.push({ tag, score: 0, matches: null });
    } else {
      const match = fuzzyMatchJs(prepared, tag.toLowerCase());
      if (match) results.push({ tag, score: match.score, matches: match.matches });
    }
  }
  results.sort((a, b) => b.score - a.score);
  return results;
}

/** Scores `text`-like suggestions: tries the last path segment first (with shifted match ranges), then the whole string. */
function s21PathSuggestion(getter, text) {
  const base = lastSegment(text);
  let result = getter(base);
  if (result) {
    shiftRanges(result.matches, text.length - base.length);
    return result;
  }
  result = getter(text);
  if (result) result.score -= 1;
  return result;
}

/** True when the given view/editor exposes a live metadata (properties) editor. */
function s21HasMetadataEditor(view) {
  return !!view && typeof view === "object" && Object.hasOwn(view, "metadataEditor") && view.metadataEditor instanceof s21Env().tO;
}

/** The metadata editor of the active editor, or of the active leaf's view when the editor has none. */
function s21ActivePropertiesEditor(workspace) {
  const activeEditor = workspace.activeEditor;
  if (s21HasMetadataEditor(activeEditor) && activeEditor.canShowProperties()) return activeEditor.metadataEditor;
  const view = workspace.activeLeaf == null ? undefined : workspace.activeLeaf.view;
  if (s21HasMetadataEditor(view) && view.canShowProperties()) return view.metadataEditor;
  return null;
}

/** Suggestions for a property value that is not a link: existing values of the same frontmatter key. */
function s21PropertyValueSuggestions(app, key, query) {
  query = query.toLowerCase();
  const results = [];
  const words = [query];
  const values = app.metadataCache.getFrontmatterPropertyValuesForKey(key);
  for (const value of values) {
    if (query === "") {
      results.push({ type: "text", text: value, score: 0, matches: null });
    } else {
      const spans = containsAllWords(words, value.toLowerCase());
      if (spans) results.push({ type: "text", text: value, score: matchScore(spans, query.length, value.length, 0), matches: spans });
    }
  }
  results.sort((a, b) => b.score - a.score);
  return results;
}

// ---- s22-consts.js ----
// s22 slice: constants, matcher placeholders, embed URL handling and the iframe
// message bridge. Replaces inherited top-level declarations; names are s22-prefixed
// because all own modules share one flat scope inside the bundle.

// Search target fields the query parser knows about.
const s22SearchFields = ["filename", "filepath", "content", "propertyName", "tag"];

// Placeholder matcher objects: stand-ins for matcher types that carry no behaviour of
// their own (they only mark "this slot is occupied" for the query UI).
function s22NoopMatcher() {}
function s22NewNoopMatcher() { return new s22NoopMatcher(); }

// Three distinct empty objects the bundle kept as separate singletons (tH, nH, sq).
const s22BlankObjectA = {};
const s22BlankObjectB = {};
const s22BlankObjectC = {};
const s22Nothing = null;

// Default sort field used by the file-explorer style sort UI.
const s22DefaultSortField = "filepath";

// Sort mode pairs offered by the sort menu, in display order.
const s22SortModePairs = [
  ["alphabetical", "alphabeticalReverse"],
  ["byModifiedTime", "byModifiedTimeReverse"],
  ["byCreatedTime", "byCreatedTimeReverse"],
];

// Localised labels for the sort modes (built lazily so `gm` is resolved at use time).
function s22SortLabels() {
  const gm = env().gm;
  return {
    alphabetical: gm.plugins.fileExplorer.labelSortAToZ,
    alphabeticalReverse: gm.plugins.fileExplorer.labelSortZToA,
    byModifiedTime: gm.plugins.fileExplorer.labelSortNewToOld,
    byModifiedTimeReverse: gm.plugins.fileExplorer.labelSortOldToNew,
    byCreatedTime: gm.plugins.fileExplorer.labelSortCreatedNewToOld,
    byCreatedTimeReverse: gm.plugins.fileExplorer.labelSortCreatedOldToNew,
  };
}

// Sort comparators for file-like objects { basename, stat: { mtime, ctime } }.
function s22SortComparators() {
  const ub = env().ub;
  const out = {
    alphabetical: (a, b) => ub(a.basename, b.basename),
    byModifiedTime: (a, b) => b.stat.mtime - a.stat.mtime,
    byCreatedTime: (a, b) => b.stat.ctime - a.stat.ctime,
  };
  // reverse modes delegate to the forward ones, like the original did
  out.alphabeticalReverse = (a, b) => -out.alphabetical(a, b);
  out.byModifiedTimeReverse = (a, b) => -out.byModifiedTime(a, b);
  out.byCreatedTimeReverse = (a, b) => -out.byCreatedTime(a, b);
  return out;
}

// Paragraph boundary used when scanning preview text for blank-line splits.
const s22ParagraphBreak = /\r?\n\r?\n/y;

// Markdown render flags object; inherited code mutates the fields after init
// (progressiveRender / listBullet are disabled for bots and old webviews).
const s22RenderFlags = { progressiveRender: true, asyncParse: true, listBullet: true };

// Windows that already have the iframe message bridge installed (one listener per window).
const s22FrameBridgeSeen = new WeakSet();

// Installs a "message" listener on `win` that re-dispatches messages coming from
// same-window iframes as "framemessage" CustomEvents on the iframe element.
function s22InstallFrameBridge(win) {
  if (s22FrameBridgeSeen.has(win)) return;
  s22FrameBridgeSeen.add(win);
  win.addEventListener("message", (event) => {
    const frames = win.document.body.findAll("iframe");
    for (let i = 0; i < frames.length; i++) {
      const frame = frames[i];
      if (frame.contentWindow === event.source) {
        frame.dispatchEvent(new CustomEvent("framemessage", { bubbles: false, detail: event }));
        return;
      }
    }
  });
}

// ---- embed URL detection (youtube-nocookie / twitter embeds) ----
const s22YoutubeUrl = /^(?:https?:\/\/)?(?:www\.|m\.)?(?:youtube\.com|youtu\.be)(?:\/(?:[\w\-]+\?(?:.*?\&)*v=|embed\/|v\/)?)([\w\-]+)(?:\??&?(?:t|start)=([0-9]+))?(?:\S+)?$/;
const s22TweetUrl = /^(?:https?:\/\/)?(?:mobile\.)?(?:twitter|x)\.com\/.+\/(\d+)/;

// Normalises a supported embed URL to the iframe src, or null when unsupported.
function s22NormalizeEmbedUrl(url) {
  if (!url || typeof url !== "string") return null;
  let m = url.match(s22YoutubeUrl);
  if (m) {
    url = "https://www.youtube-nocookie.com/embed/" + m[1];
    if (m[2]) url += "?start=" + m[2];
    return url;
  }
  m = url.match(s22TweetUrl);
  if (m) {
    const dark = document.body.hasClass("theme-dark");
    return "https://platform.twitter.com/embed/Tweet.html?dnt=true&theme=" + (dark ? "dark" : "light") + "&id=" + m[1];
  }
  return null;
}

// Builds the sandboxed iframe used for external embeds; twitter gets extra sizing
// handling through the twttr.embed resize message.
function s22CreateEmbedFrame(src) {
  const frame = env().createEl("iframe", "external-embed mod-receives-events");
  frame.setAttr("sandbox", "allow-forms allow-presentation allow-same-origin allow-popups-to-escape-sandbox allow-scripts allow-modals allow-popups");
  frame.setAttr("allow", "fullscreen");
  frame.setAttr("frameborder", "0");
  frame.setAttr("referrerpolicy", "strict-origin-when-cross-origin");
  frame.src = src;
  if (src.includes("platform.twitter.com")) {
    frame.setAttr("scrolling", "no");
    frame.addEventListener("framemessage", (event) => {
      const detail = event.detail;
      if (!detail) return;
      const data = detail.data;
      if (!data) return;
      const inner = data["twttr.embed"];
      if (inner && inner.method === "twttr.private.resize") {
        const height = inner.params[0].height;
        if (Number.isNumber(height)) frame.style.height = String(Math.min(1000, height)) + "px";
      }
    });
    s22InstallFrameBridge(frame.win);
    frame.onWindowMigrated(() => s22InstallFrameBridge(frame.win));
  }
  return frame;
}

// ---- s22-lazy.js ----
// s22 slice: lazy third-party script loaders (pdf.js, CodeMirror modes, mermaid,
// prism, MathJax) and the small promise getters / MathJax render helpers that go with them.
// The loaders delegate to the app's own script loader (`Hv`); the returned objects keep
// the same `{ promise }` shape the inherited code expects.

const s22Hv = () => env().Hv;
const s22Jl = () => env().Jl;

// ---- pdf.js ----
let s22PdfLib = null;
